package net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueobject.SenderEmailVO;

class SenderEmailValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of sender email of smtp outbound config")
  void test_sender_email_value_holder_assign_plain_value() {
    Object holder = new Object();
    SenderEmailValueHolder<Object> value = new SenderEmailValueHolder<>(holder);
    Assertions.assertSame(holder, value.senderEmail("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getSenderEmailValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getSenderEmail().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of sender email of smtp outbound config")
  void test_sender_email_value_holder_assign_value_object() {
    Object holder = new Object();
    SenderEmailValueHolder<Object> value = new SenderEmailValueHolder<>(holder);
    SenderEmailVO vo = SenderEmailVO.from("one");
    Assertions.assertFalse(value.getSenderEmailValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.senderEmail(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSenderEmailValue().orElseThrow());
    Assertions.assertSame(holder, value.senderEmail(Optional.empty()));
    Assertions.assertFalse(value.getSenderEmailValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.senderEmail(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSenderEmailValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of sender email of smtp outbound config against the original")
  void test_sender_email_value_holder_read() {
    Object holder = new Object();
    SenderEmailValueHolder<Object> value = new SenderEmailValueHolder<>(holder);
    SenderEmailVO vo = SenderEmailVO.from("one");
    SenderEmailVO other = SenderEmailVO.from("one");
    SmtpOutboundConfig original = Mockito.mock(SmtpOutboundConfig.class);
    Mockito.when(original.getSenderEmailValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSenderEmail(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readSenderEmail(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.senderEmail(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSenderEmail(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSenderEmail(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of sender email of smtp outbound config")
  void test_sender_email_value_holder_unset() {
    Object holder = new Object();
    SenderEmailValueHolder<Object> value = new SenderEmailValueHolder<>(holder);
    SenderEmailVO vo = SenderEmailVO.from("one");
    value.senderEmail(vo);
    Assertions.assertSame(holder, value.unsetSenderEmailIfMatches("senderEmail_other"));
    Assertions.assertTrue(value.getSenderEmailValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSenderEmailIfMatches("senderEmail"));
    Assertions.assertFalse(value.getSenderEmailValue().isPresent(),
        "The field name must clear the value");
    value.senderEmail(vo);
    Assertions.assertSame(holder, value.unsetSenderEmail());
    Assertions.assertFalse(value.getSenderEmailValue().isPresent(), "Unset must clear the value");
  }
}
